function buildCommand() {
  const __args = [['iplookup', 'getip'], 'Utility', 'Look up info about an IP address', async ({ sock, from, msg, args }) => {
  const ip = args[0];
  if (!ip) return sock.sendMessage(from, { text: 'Usage: .iplookup 8.8.8.8' }, { quoted: msg });
  try {
    const res = await fetch(`http://ip-api.com/json/${ip}`);
    const d = await res.json();
    await sock.sendMessage(from, { text: `🌍 *${ip}*\nCountry: ${d.country}\nCity: ${d.city}\nISP: ${d.isp}` }, { quoted: msg });
  } catch (e) {
    await sock.sendMessage(from, { text: 'Could not look up that IP.' }, { quoted: msg });
  }
}];
  const [commandsArr, section, description, handler, opts = {}] = __args;
  return { commands: commandsArr, section, description, handler, ownerOnly: !!opts.ownerOnly };
}

module.exports = buildCommand();
